import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"索引","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/index-drives.md","filePath":"zh-TW/user-guide/settings/index-drives.md","lastUpdated":1786506886000}'),n={name:"zh-TW/user-guide/settings/index-drives.md"};function a(i,o,l,d,g,c){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h1><p>按順序共五個分頁：<strong>本機磁碟機</strong>、<strong>網路磁碟機</strong>、<strong>WSL</strong>（只在偵測到發行版時才出現）、<strong>資料夾</strong>、<strong>排除規則</strong>。</p><h2 id="本機磁碟機" tabindex="-1">本機磁碟機 <a class="header-anchor" href="#本機磁碟機" aria-label="Permalink to &quot;本機磁碟機&quot;">​</a></h2><ul><li>頂部狀態卡片彙總已索引的磁碟機數量與項目數量，並提供<strong>重建索引</strong>按鈕做全量重新掃描。</li><li>每個本機磁碟機一行：<strong>啟用/停用核取方塊</strong>、磁碟機名稱、檔案系統（NTFS/ReFS 等）、目前狀態、已索引項目數，以及每行獨立的<strong>重建</strong>/<strong>移除</strong>操作——重建進行中時還會出現<strong>停止</strong>操作（真正的 NTFS 走 $MFT 掃描沒有安全的中斷點，是唯一的例外）。</li><li>NTFS 和 ReFS 磁碟透過 Windows USN 記錄檔持續追蹤變更；其他本機檔案系統（FAT32、exFAT 等）沒有記錄檔可讀，改為直接監看檔案系統變化。不管哪種方式，手動重建都很少需要，但如果發現內容不同步，隨時可以用它——如果重建過程中被中斷（手動停止，或者應用程式/服務中途重新啟動），下次會從中斷的地方繼續，而不是從頭再來。</li></ul><p>已啟用磁碟機的選擇會被嚴格保留：如果清除全部核取方塊，本機磁碟索引會保持停用，不會再悄悄把所有磁碟機選回來。對於舊版本中以「空清單」表示「全部磁碟機」的現有設定，升級時會進行一次移轉，避免索引被意外停用。</p><p>重建期間搜尋照常可用。正在重建的磁碟機會繼續用它先前的索引回應，直到新索引就緒；其餘磁碟機完全不受影響——重建不會讓你面對一個空的結果清單。</p><h2 id="網路磁碟機" tabindex="-1">網路磁碟機 <a class="header-anchor" href="#網路磁碟機" aria-label="Permalink to &quot;網路磁碟機&quot;">​</a></h2><ul><li>與本機磁碟機相同的狀態卡片和<strong>重建索引</strong>按鈕。</li><li>每個已對應的網路磁碟機一行：啟用核取方塊、路徑/名稱、狀態（索引中 / 就緒 / 已快取 / 失敗 / 等待中 / 已連線）、項目數，以及<strong>重新整理模式</strong>下拉式選單： <ul><li><strong>手動</strong> —— 只在手動觸發（重建索引）時重新整理。</li><li><strong>每 15 分鐘</strong></li><li><strong>每小時</strong></li><li><strong>每天</strong></li></ul></li></ul><p>網路共用沒有本機 NTFS 磁碟區那樣的變更記錄檔可供監看，所以採用定時重新整理而不是即時更新。掃描引擎內建了分支祖先路徑堆疊與符號連結迴圈檢測機制，即使 NAS/SMB 共享上存在指向父目錄的軟連結或重解析點，也能自動攔截無窮迴圈，確保索引數量準確不膨脹。</p><h2 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h2><p>只有偵測到至少一個 WSL 發行版時才會出現——形態和網路磁碟機一樣（狀態卡片、<strong>重建索引</strong>按鈕，每個發行版一行，顯示狀態/項目數/<strong>重新整理模式</strong>）。發行版是自動偵測的，沒有手動「新增」這一步。</p><h2 id="資料夾" tabindex="-1">資料夾 <a class="header-anchor" href="#資料夾" aria-label="Permalink to &quot;資料夾&quot;">​</a></h2><p>單獨索引任意資料夾，而不是整個磁碟機或共用——適合只想索引某一個子目錄，而不想把這個磁碟/共用下的其他內容也納入索引的情境。</p><ul><li><strong>新增資料夾</strong>按鈕會開啟資料夾選擇器；<strong>重建索引</strong>按鈕會重新掃描清單中的所有資料夾。</li><li>每個已新增的資料夾一行：啟用核取方塊、路徑、狀態、項目數，以及和網路磁碟機一樣的<strong>重新整理模式</strong>下拉式選單（手動 / 每 15 分鐘 / 每小時 / 每天）——資料夾和網路共用一樣按排程掃描，而不是持續即時追蹤。</li><li>資料夾選擇器也支援直接選一個 <strong>UNC 網路共用路徑</strong>（比如 <code>\\\\server\\share</code>，或者它裡面的子目錄）——在選擇器裡透過「網路」瀏覽過去即可，適合只想索引某一個共用或子目錄，而不想把整台伺服器都加成對應的網路磁碟機。</li></ul><h2 id="排除規則" tabindex="-1">排除規則 <a class="header-anchor" href="#排除規則" aria-label="Permalink to &quot;排除規則&quot;">​</a></h2><p>三個子分頁，形態完全一致：一個單條輸入框 + <strong>新增</strong>按鈕，一個可編輯/刪除每一條規則的清單，以及一個批次多行文字框，配 <strong>從清單產生</strong> / <strong>套用到清單</strong>兩個按鈕，用來一次性編輯全部規則。</p><ul><li><strong>路徑排除</strong> —— 完整路徑或環境變數（例如 <code>D:\\Cache</code>、<code>%ProgramData%</code>）。</li><li><strong>Glob 萬用字元</strong> —— <code>*</code>（檔名中任意字元）、<code>?</code>（單一字元）、<code>**</code>（遞迴目錄）。範例：<code>*.tmp</code>、<code>**/node_modules/**</code>、<code>bin/**</code>。</li><li><strong>正規表示式</strong> —— 針對路徑/檔名做部分比對的任意正規表示式。範例：<code>^\\.</code>（隱藏檔案）、<code>~$</code>（Office 暫存檔）、<code>\\.git\\</code>。</li></ul><p>排除規則對本機、網路、資料夾索引都生效，套用排除規則的改動後，網路磁碟機/資料夾會自動重新掃描。</p>',18)])])}const p=t(n,[["render",a]]);export{u as __pageData,p as default};
